#fucntion to convert c to pf
def c_to_p(c):
	return 2 - 9/(8*c) # from Musharoff et al. 

## Function to convert pf to beta ##
def decimal_to_fraction(decimal_num):
    """
    Converts a decimal number (float, string, or Decimal) to a simplified fraction.

    For floats, it is recommended to pass a string representation to avoid 
    floating-point precision issues.
    """
    # Convert to string if the input is a float to maintain precision
    if isinstance(decimal_num, float):
        decimal_str = str(decimal_num)
        # Use the string constructor for accuracy
        return Fraction(decimal_str)

    # Directly use the constructor for string or Decimal inputs
    return Fraction(decimal_num)
def pf_to_beta(pf):
    """
    Convert the input proportion of females (float) into the ratio of females to males
    """
    pf_frac = decimal_to_fraction(pf)
    Nf = pf_frac.numerator
    Nm = pf_frac.denominator - pf_frac.numerator
    
    beta = Nf / Nm
    
    if beta < 1:
        return round(beta, 9) 
    else:
        return(round(beta, 3))



#### Dadi Demogrpahic Models # ------------------------------------------------------------------------- #

def two_epoch_A(params, ns, pts):
	"""
	Two epoch size change model to fit Autosomal data 
	params = (nu, T)
	"""
	nu, T = params

	xx = dadi.Numerics.default_grid(pts)

	phiA = dadi.PhiManip.phi_1D(xx)

	phiA = dadi.Integration.one_pop(phiA, xx, T=T, nu=nu)

	fsA = dadi.Spectrum.from_phi(phiA, ns, (xx,))
	return fsA 


def two_epoch_X_const(params, ns, pts):
	"""
	Modified from Musharoff et al. 2019 
	Pair with two_epoch_A, fix autosomal demographic parameters and infer c, parameter summarizing BSR
	This model assumes a 1:1 BSR, used as nested model for LRT 
	
	Adjust T and theta to maintain continuity with Autosome 

	"""

	nu, T_auto, theta_auto, c = params

	#constraints - given a 1:1 BSR, ensure that theta X is 3/4 theta A 
	T = 4.0 / 3 * T_auto
	theta = 3.0 / 4 * theta_auto


	xx = dadi.Numerics.default_grid(pts)

	phiX = dadi.PhiManip.phi_1D(xx, theta0 = theta)
	phiX = dadi.Integration.one_pop(phiX, xx, T, nu, theta0=theta)

	fsX = XseqRatio * muX_muA_ratio * dadi.Spectrum.from_phi(phiX, ns, (xx,)) ##XseqRatio * muX_muA_ratio account for differences in L and mu such that theta differences are directly attributable to the BSR 

	return fsX 


def two_epoch_X_BSR(params, ns, pts):
	"""
	Modified from Musharoff et al. 2019

	Pair with two_epoch_A, fit X fs but allow for a constant, but unbalanced BSR 
	"""
	nu, T_auto, theta_auto, c = params

	# constraints - now a function of c
	T = 1.0 / c * T_auto
	theta = c * theta_auto

	xx = dadi.Numerics.default_grid(pts)

	phiX = dadi.PhiManip.phi_1D(xx, theta0 = theta)
	phiX = dadi.Integration.one_pop(phiX, xx, T, nu, theta0=theta)

	fsX = XseqRatio * dadi.Spectrum.from_phi(phiX, ns, (xx,)) ##XseqRatio * muX_muA_ratio account for differences in L and mu such that theta differences are directly attributable to the BSR 
	return fsX 


def three_epoch_A(params, ns, pts):
	"""
	Infer four demographic parameters, ignoring BSR 
	numain = size change during epoch 1 (Immediately following ancestral Epoch)
	nucurr = size change during epoch 2 (current epoch, most recent in time)
	
	Tmain = timing of transition from ancestral epoch to epoch 1 
	Tcurr = timing of transition from epoch 1 to epoch 2 
	""" 
	numain, nucurr, Tmain, Tcurr  = params

	xx = dadi.Numerics.default_grid(pts)

	phiA = dadi.PhiManip.phi_1D(xx)
	phiA = dadi.Integration.one_pop(phiA, xx, T=Tmain, nu=numain)
	phiA = dadi.Integration.one_pop(phiA, xx, T=Tcurr, nu=nucurr)

	fsA = dadi.Spectrum.from_phi(phiA, ns, (xx,))

	return fsA 


def three_epoch_X_const(params, ns, pts):

	## Fix demographic parameters, adjusting for X based on 1:1 BSR 
	numain, nucurr, Tmain_A, Tcurr_A, theta_auto, c = params

	# constraints - constant assuming a 1:1 BSR 
	Tmain = 4.0 / 3 * Tmain_A
	Tcurr = 4.0 / 3 * Tcurr_A
	theta = 3.0 / 4 * theta_auto
	
	xx = dadi.Numerics.default_grid(pts)

	phiX = dadi.PhiManip.phi_1D(xx)
	phiX = dadi.Integration.one_pop(phiX, xx, T=Tmain, nu=numain, theta0=theta)
	phiX = dadi.Integration.one_pop(phiX, xx, T=Tcurr, nu=nucurr, theta0=theta)

	fsX = XseqRatio * muX_muA_ratio * dadi.Spectrum.from_phi(phiX, ns, (xx,)) ##XseqRatio * muX_muA_ratio account for differences in L and mu such that theta differences are directly attributable to the BSR 

	return fsX 


def three_epoch_X_BSR(params, ns, pts):

	## Fix demographic parameters, adjust for X based on freely inferred c (NeX/NeA)
	numain, nucurr, Tmain_A, Tcurr_A, theta_auto, c = params

	# constraints - as a function of c 
	Tmain = 1.0 / c * Tmain_A
	Tcurr = 1.0 / c * Tcurr_A
	theta = c * theta_auto
	
	xx = dadi.Numerics.default_grid(pts)

	phiX = dadi.PhiManip.phi_1D(xx)
	phiX = dadi.Integration.one_pop(phiX, xx, T=Tmain, nu=numain, theta0=theta)
	phiX = dadi.Integration.one_pop(phiX, xx, T=Tcurr, nu=nucurr, theta0=theta)

	fsX = XseqRatio * muX_muA_ratio * dadi.Spectrum.from_phi(phiX, ns, (xx,))

	return fsX 

