### Fit Demographic Model for A ## -------------------------------------------------------------------- # 

# use dadiLrtFunctions.py in Musharoff github? 
def fit_two_epoch_A(Adata, outfileA, modelfileA, start_params, upper_bounds, lower_bounds, iters=100):
	"""
	Adapted from Musharoff et al. 2019 
	"""
	# read in data 
	data = dadi.Spectrum.from_file(Adata)

	ns = data.sample_sizes

	model_A = dadi.Numerics.make_extrap_func(two_epoch_A)

	## iterate i times to optimize parameters, storing the parameter combination with the best log-likelihood 

	ll_opt = -1000000 # start with generic low log likelihood 
	popt_final = None
	theta_opt = None
	model_opt = None
	for i in range(iters):
		p0 = dadi.Misc.perturb_params(start_params, lower_bound = lower_bounds, upper_bound = upper_bounds)

		p_i = dadi.Inference.optimize(p0, data, model_A, pts_l, lower_bound = lower_bounds, upper_bound = upper_bounds, maxiter=600)

		model_i = model_A(p_i, ns, pts_l)

		ll_i = dadi.Inference.ll_multinom(model_i, data)

		theta_i = dadi.Inference.optimal_sfs_scaling(model_i, data)

		if ll_i > ll_opt:
			popt_final = p_i
			theta_opt = theta_i 
			ll_opt = ll_i 
			model_opt = model_i


	nuhat = popt_final[0]
	T_hat = popt_final[1]

	## output the modelfile and outfile 
	with open(outfileA, 'w') as outF:
		outF.write("Optimized parameters " + repr(popt_final) + "\n")
		outF.write(
			"Optimized log-likelihood: " + str(ll_opt) + "; theta: " + str(theta_opt) + "\n"
		)
		# outF.write('{.7f} {.7f} {.7f} {.7f}'.format(nuhat, tauhat, theta, ll_opt))   # hard-coded for two params. TODO get the float formatting to work
		outF.write(
			"{} {} {} {}\n".format(nuhat, T_hat, ll_opt, theta_opt)
		)  # hard-coded for two params

	model_opt.to_file(modelfileA)
	return (popt_final, ll_opt, theta_opt)

def fit_two_epoch_X(Aparams, Xdata, funcName, start_params, upper_bounds, lower_bounds, iters = 100):
	"""
	Adapted from Musharoff et al. 2019 

	Aparams, tuple output from fit_two_epoch_A

	Return poptX = [nuX, TX, thetaX, c] and ll_optX 
	"""
	data = dadi.Spectrum.from_file(Xdata)
	ns = data.sample_sizes

	poptA = Aparams[0]
	ll_optA = Aparams[1]
	thetaA = Aparams[2]

	nuA = poptA[0]
	TA = poptA[1]


	if funcName == 'two_epoch_X_const': # fixed c such that BSR = 1:1
		popt_start = [nuA, TA, thetaA, 0.75] # c = 0.75, do not optimize but fix everything at these values 
		func = two_epoch_X_const
		#create model function
		func_ex = dadi.Numerics.make_extrap_log_func(func)
		# return log-likelihood for model given fixed params (1:1 BSR)
		modelX = func_ex(popt_start, ns, pts_l)
		ll_optX = dadi.Inference.ll(modelX, data)
		TX = 4.0/3 * TA
		thetaX = 4.0/3 * thetaA
		popt_X = [nuA, TX, thetaX, 0.75]

		with open("const_"+outfileX, "a") as outF:
			outstr = lrt.format1DParams(funcName, popt_X, theta=thetaX, ll_opt=ll_optX)
			outF.write(outstr)
		modelX.to_file("const_"+modelfileX)

		return (popt_X, ll_optX) ## TODO: write output file? 

	elif funcName == 'two_epoch_X_BSR': # c is a free parameter 
		popt_start =  [nuA, TA, thetaA, 0.75]
		func = two_epoch_X_BSR
		func_ex = dadi.Numerics.make_extrap_log_func(func)

		fixed_params = [nuA, TA, thetaA, None] # fix A params 


		ll_optX = -1000000
		popt_X = None
		model_opt = None
		for i in range(iters): # optimize 100 times, replacing the best parameters if iteration reveals higher log likelihood 
			p_0 = dadi.Misc.perturb_params(popt_start, upper_bound = upper_bounds, lower_bound = lower_bounds)
			
			p_i = dadi.Inference.optimize(p_0, data, func_ex, pts_l, upper_bound=upper_bounds, lower_bound=lower_bounds, fixed_params=fixed_params, maxiter = 600)

			model_i = func_ex(p_i, ns, pts_l)

			ll_i = dadi.Inference.ll(model_i, data)

			if ll_i > ll_optX:
				popt_X = p_i
				ll_optX = ll_i 
		
				model_opt = model_i
		with open("inferred_"+outfileX, "a") as outF:
			outstr = lrt.format1DParams(funcName, popt_X, theta=popt_X[2], ll_opt=ll_optX)
			outF.write(outstr)
		model_opt.to_file("inferred_"+modelfileX)

				
		return (popt_X, ll_optX) ## TODO: write output file? 



## Repeat process above, but for more complex demographic model
def fit_three_epoch_A(Adata, outfileA, modelfileA, start_params, upper_bounds, lower_bounds, iters=100):
	"""
	Adapted from Musharoff et al. 2019 
	"""
	# read in data 
	data = dadi.Spectrum.from_file(Adata)

	ns = data.sample_sizes

	model_A = dadi.Numerics.make_extrap_func(three_epoch_A)

	## iterate i times to optimize parameters, storing the parameter combination with the best log-likelihood 

	ll_opt = -10000000
	popt_final = None
	theta_opt = None
	model_opt = None
	for i in range(iters):
		p0 = dadi.Misc.perturb_params(start_params, lower_bound = lower_bounds, upper_bound = upper_bounds)

		p_i = dadi.Inference.optimize(p0, data, model_A, pts_l, lower_bound = lower_bounds, upper_bound = upper_bounds, maxiter=600)

		model_i = model_A(p_i, ns, pts_l)

		ll_i = dadi.Inference.ll_multinom(model_i, data)

		theta_i = dadi.Inference.optimal_sfs_scaling(model_i, data)

		if ll_i > ll_opt:
			popt_final = p_i
			theta_opt = theta_i 
			ll_opt = ll_i 
			model_opt = model_i


	nu_main_hat = popt_final[0]
	nu_curr_hat = popt_final[1]
	T_main_hat = popt_final[2]
	T_curr_hat = popt_final[3]

	## output the modelfile and outfile (as presented in Musharoff et al. appraoch)
	with open(outfileA, 'w') as outF:
		outF.write("Optimized parameters " + repr(popt_final) + "\n")
		outF.write(
			"Optimized log-likelihood: " + str(ll_opt) + "; theta: " + str(theta_opt) + "\n"
		)
		
		outF.write(
			"{} {} {} {} {} {}\n".format(nu_main_hat, nu_curr_hat, T_main_hat, T_curr_hat, ll_opt, theta_opt)
		)  # hard-coded for two params

	model_opt.to_file(modelfileA)
	return (popt_final, ll_opt, theta_opt)

def fit_three_epoch_X(Aparams, Xdata, funcName, start_params, upper_bounds, lower_bounds, iters = 100):
	"""
	Adapted from Musharoff et al. 2019 

	Aparams, tuple output from fit_two_epoch_A

	Return poptX = [nuX, TX, thetaX, c] and ll_optX 
	"""
	data = dadi.Spectrum.from_file(Xdata)
	ns = data.sample_sizes

	poptA = Aparams[0]
	ll_optA = Aparams[1]
	thetaA = Aparams[2]

	nu_mainA = poptA[0]
	nu_currA = poptA[1]
	T_mainA = poptA[2]
	T_currA = poptA[3]


	if funcName == 'three_epoch_X_const': # fixed c such that BSR = 1:1
		popt_start = [nu_mainA, nu_currA, T_mainA, T_currA, thetaA, 0.75] # c = 0.75, do not optimize but fix everything at these values 
		func = three_epoch_X_const
		func_ex = dadi.Numerics.make_extrap_log_func(func)
		modelX = func_ex(popt_start, ns, pts_l)
		ll_optX = dadi.Inference.ll(modelX, data)
		T_mainX = 4.0/3 * T_mainA
		T_currX = 4.0/3 * T_mainX
		thetaX = 4.0/3 * thetaA
		popt_X = [nu_mainA, nu_currA, T_mainX, T_currX, thetaX, 0.75]

		return (popt_X, ll_optX) ## TODO: write output file? 

	elif funcName == 'three_epoch_X_BSR': # c is a free parameter 
		popt_start = [nu_mainA, nu_currA, T_mainA, T_currA, thetaA, 0.75]
		func = three_epoch_X_BSR
		func_ex = dadi.Numerics.make_extrap_log_func(func)

		fixed_params = [nu_mainA, nu_currA, T_mainA, T_currA, thetaA, None] # fix A params 


		ll_optX = -1000000
		popt_X = None
		model_opt = None
		for i in range(iters): # optimize 100 times, replacing the best parameters if iteration reveals higher log likelihood 
			p_0 = dadi.Misc.perturb_params(popt_start, upper_bound = upper_bounds, lower_bound = lower_bounds)
			
			p_i = dadi.Inference.optimize(p_0, data, func_ex, pts_l, upper_bound=upper_bounds, lower_bound=lower_bounds, fixed_params=fixed_params, maxiter = 600)

			model_i = func_ex(p_i, ns, pts_l)

			ll_i = dadi.Inference.ll(model_i, data)

			if ll_i > ll_optX:
				popt_X = p_i
				ll_optX = ll_i 
				model_opt = model_i
				
		return (popt_X, ll_optX) 

