### Infer the BSR and demographic model 

def run_sb_two_epoch(fsA, fsX, outfileA, modelfileA):

	(poptA, lloptA, thetaA) = fit_two_epoch_A(fsA, outfileA, modelfileA, start_params, upper_bounds, lower_bounds) # run and output Autosomal model 

	const_X = fit_two_epoch_X((poptA, lloptA, thetaA), fsX, 'two_epoch_X_const', startX, upperX, lowerX) # fit X based on autosomal parameters, assume 1:1 BSR
	BSR_X = fit_two_epoch_X((poptA, lloptA, thetaA), fsX, 'two_epoch_X_BSR', startX, upperX, lowerX) # fit X based on autosomal parameters, c is a free parameter

	return(const_X, BSR_X)


# def run_sb_MR(fsA, fsX, outfileA, modelfileA): 
def run_sb_three_epoch(fsA, fsX, outfileA, modelfileA):

	(poptA, lloptA, thetaA) = fit_three_epoch_A(fsA, outfileA, modelfileA, start_params, upper_bounds, lower_bounds)

	const_X = fit_three_epoch_X((poptA, lloptA, thetaA), fsX, 'three_epoch_X_const', startX, upperX, lowerX)
	BSR_X = fit_three_epoch_X((poptA, lloptA, thetaA), fsX, 'three_epoch_X_BSR', startX, upperX, lowerX)

	return (const_X, BSR_X)



